    function setUp() public {

        token = IMyBond(TARGET);
        owner = token.owner();
        victim = vm.addr(1);

        uint256 victimInitialBalance = 1000 * 1e18;
        deal(TARGET, victim, victimInitialBalance);

        assertEq(token.balanceOf(victim), victimInitialBalance);
    }

